&lt;li style=&quot;font-weight: 400;&quot;&gt;&lt;a href=&quot;https://about.gitlab.com/handbook/stock-options/&quot;&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Equity Compensation &amp;amp; Employee Stock Purchase Plan&lt;/span&gt;&lt;/a&gt;&lt;/li&gt;
